thomasmoore:{"n":"Thomas Moore","d":"Oldham","s":"y","p":[],"r":["uk"],"t":"A joiner of Oldham, Lancashire, named as Martha Moore's father when she married Henry Warbrick in 1865.","src":[["Marriage, Holy Trinity, Oldham, 12 Mar 1865 (FreeREG)","https://www.freereg.org.uk/search_queries/new"]]},
victor:{n:"Victor White",d:"m. 1872 Queensland",s:"y",p:[],r:["au"],t:"Married Mary Stewart McGregor in Queensland on 14 September 1872; their daughter Adele was born the next August.\n\nThe only Victor White in Brisbane's newspapers of the 1870s was an ironmonger who lived in North Brisbane and kept a shop in Queen Street, opposite the Government Savings Bank, selling ironmongery and musical instruments. A wedding was held at his house at the end of 1874. In 1877 he was fined for setting out goods on the footpath, Mrs Victor White sailed for Sydney on the Tambaroora in March, and in November the Supreme Court declared him insolvent. No Queensland death has been found for him.",src:[["Victor White, ironmonger, advertisement, The Telegraph, 25 Apr 1877","https://trove.nla.gov.au/search/category/newspapers?keyword=%22Victor%20White%22%20ironmonger"],["Insolvency notice, The Brisbane Courier, 3 Nov 1877","https://trove.nla.gov.au/newspaper/article/1367585"],["Queensland BDM family history search","https://familyhistory.bdm.qld.gov.au/"]]},
marys:{"n":"Mary Stewart McGregor","d":"c. 1851–1927 · Brisbane","x":1927,"s":"y","p":["alexmc","janetb"],"r":["au"],"src":[["Queensland BDM family history search","https://familyhistory.bdm.qld.gov.au/"],["Death notice, Queensland Figaro, 19 Mar 1927","https://nla.gov.au/nla.news-article84900359"]],"t":"She married Victor White in Queensland in 1872. She later lived in Sydney, and died at St Martin's Hospital, Brisbane, on 10 March 1927, in her 76th year. Her death notice names four daughters: Mrs F. Warbrick (Adele), Mrs T. Latcham, and Eugenie and Muriel White.","b":1851},
