janwijnstra:{"n":"Jan Jilts Wijnstra","s":"h","p":[],"r":["nl"],"t":"Of Hemrik in Opsterland; father of Jilt Jans Wijnstra, who carried his grandfather's name Jilt.","src":[["Marriage of Jilt Wijnstra, 1856","https://www.openarchieven.nl/frl:e5ed003c-34be-f6df-4c21-e6d5d4c808c9"]]},
albertjedv:{"n":"Albertje Hendriks de Vries","s":"h","p":[],"r":["nl"],"t":"Mother of Jilt Jans Wijnstra, the Lippenhuizen farmer.","src":[["Death of Jilt Wijnstra, 1872","https://www.openarchieven.nl/frl:f67a6664-5de2-b4a1-5e25-620b05da8dc8"]]},
