jansikkes:{"n": "Jan Sikkes", "d": "d. 1809 · Rauwerd", "x": 1809, "s": "h", "p": [], "r": ["nl"], "t": "Father of Johannes Jans Elzinga. He died at Rauwerd on 12 February 1809, before Frisians were made to take fixed surnames in 1811.", "src": [["Marriage, Idaarderadeel, 1815", "https://www.openarchieven.nl/frl:6cf369ac-e86f-e02c-8906-f1d707c1a474"]]},
